                                count--;
                            }
                            else {
                                bool isStruct = fragments[index].Equals( "STRUCT", StringComparison.InvariantCultureIgnoreCase );
                                if ( isStruct ) {
                                    count++;
                                }
                                else {
                                    structPart.Add( fragments[index] );
                                }
