                        break;
                    case 4:
                        bean.setCourseGs(tds.get(j).text());
                        break;
                    case 5:
                        bean.setCourseBk(tds.get(j).text());
                        break;
                    case 6:
                        bean.setCourseCx(tds.get(j).text());
                        break;
                    case 7:
                        bean.setCourseXf(tds.get(j).text());
                        break;
                    case 8:
                        bean.setCourseBj(tds.get(j).text());
